function planMedia(key){return planExtras[key]||exerciseMedia[key]}
function sessionRows(){return sessions[day].items.map(([id,title,reps,note,rest])=>({id,title,reps,note,rest}))}
function setKey(id,i){return `${day}:${id}:${i}`}
function setLog(){return read(todayKey()+'-sets',{})}
function sessionProgress(){const log=setLog(),items=sessionRows();let total=0,done=0;items.forEach(e=>e.reps.forEach((_,i)=>{total++;if(log[setKey(e.id,i)])done++}));return {done,total,percent:Math.round(done/total*100)}}
function workout(){const s=sessions[day],p=sessionProgress(),log=setLog();return `<div class="training-wrap wrap"><div class="training-title"><div><a class="breadcrumb" href="#home">← 返回手册</a><div class="eyebrow">DAY ${s.no} · WORKOUT</div><h1>三分化 · ${s.muscles}</h1></div><span class="training-stamp">谭师<br><small>训练计划</small></span></div><div class="training-intro"><p>好好吃饭，好好睡觉，<br>好好训练，好好生活。</p><span>#谭成义 <i>／</i> 今天也认真练。</span></div><div class="training-section-head"><h2>今天练哪一部分？</h2><span>点击切换训练日</span></div><div class="day-cards">${Object.entries(sessions).map(([key,x])=>`<button data-day="${key}" class="day-card ${key===day?'selected':''}" aria-pressed="${key===day}"><strong>${x.label}<span>${key===day?'✓':'↗'}</span></strong><small>${x.muscles}</small><span>5 个动作 · ${key===day?'已选中':x.en}</span></button>`).join('')}</div><section class="session-progress" aria-label="训练完成进度"><div><span class="subtle">今日进度</span><div><strong id="completed-sets">${p.done}</strong><span> / ${p.total} 组</span></div></div><strong id="progress-percent">${p.percent}%</strong><div class="progress-track"><span id="sets-progress-bar" style="width:${p.percent}%"></span></div><p><span>按已完成的正式组计算，不含热身</span><span>5 个动作</span></p></section><details class="warmup-panel" open><summary><span><strong>热身激活</strong><small>${s.muscles} · ${s.warm.length} 项</small></span><span class="collapse-label">展开 / 收起</span></summary><div class="warmup-list">${s.warm.map(([id,dose],i)=>{const m=planMedia(id);return `<div class="warmup-item"><button class="exercise-thumb" data-demo="${id}" aria-label="查看${esc(m.title)}动态示范"><img src="media/opengym/${m.id}.webp" alt="${esc(m.title)}静态示例" width="180" height="180" loading="lazy"><span aria-hidden="true">▶</span></button><span class="warmup-number">${String(i+1).padStart(2,'0')}</span><div><strong>${m.title}</strong><small>${dose} · 1 组</small></div><button class="demo-link" data-demo="${id}">看示范</button></div>`}).join('')}</div><p class="warmup-footnote">先轻活动，再按顺序热身；正式动作前另做轻重量热身组。参考变式在示范中说明。</p></details><div class="training-section-head"><h2>动作清单</h2><span>点击组次完成 · 再点可撤销</span></div><div class="exercise-cards">${sessionRows().map((e,i)=>{const m=planMedia(e.id),done=e.reps.filter((_,j)=>log[setKey(e.id,j)]).length;return `<section class="training-card" id="plan-${e.id}"><div class="training-card-top"><span>动作 ${i+1}</span><span data-exercise-progress="${e.id}">${done}/${e.reps.length} 组</span></div><div class="training-exercise-head"><button class="exercise-thumb" data-demo="${e.id}" aria-label="查看${esc(e.title)}动态示范"><img src="media/opengym/${m.id}.webp" alt="${esc(e.title)}静态示例" width="180" height="180" loading="lazy"><span aria-hidden="true">▶</span></button><div><button class="exercise-title" data-demo="${e.id}">${e.title} <span>↗</span></button><div class="exercise-en">${m.name}</div><div class="exercise-target">RPE 8 · 组间休息 ${e.rest} 秒</div><p>${e.note}</p></div></div><div class="set-grid" role="group" aria-label="${esc(e.title)}组次">${e.reps.map((r,j)=>`<button class="set-button ${log[setKey(e.id,j)]?'complete':''}" data-set="${e.id}:${j}" aria-label="${esc(e.title)}第 ${j+1} 组 ${r} 次" aria-pressed="${!!log[setKey(e.id,j)]}"><span class="set-index">${j+1}</span><strong>${r}<small> 次</small></strong><span class="set-status">${log[setKey(e.id,j)]?'已完成 ✓':'完成'}</span></button>`).join('')}</div></section>`}).join('')}</div><div class="training-bottom-note">单侧动作以左右完成记为一组。完成记录保存在当前浏览器，按日期区分；热身不计入正式组数。</div></div><div class="session-dock"><div class="rest-dock" hidden><span>组间休息 <strong id="timer">02:00</strong></span><button id="timer-toggle">暂停</button><button id="timer-skip">跳过休息 →</button></div><div class="session-actions"><button id="reset-session">重置${s.label}</button><button class="primary" id="start-session">${p.done===p.total?'今日训练已完成 ✓':p.done?'继续训练 →':'开始训练 →'}</button></div></div><dialog id="exercise-demo-dialog"><div class="dialog-head"><div><div class="eyebrow">MOVEMENT STUDY</div><h2 id="demo-title"></h2></div><button type="button" id="close-demo" aria-label="关闭动态示范">×</button></div><video id="demo-video" controls playsinline muted loop preload="metadata" width="180" height="180"></video><div class="demo-playback"><button id="demo-play">播放示范</button><label>播放速度 <select id="demo-speed"><option value="0.5">0.5× 慢速</option><option value="0.75">0.75×</option><option value="1" selected>1× 正常</option></select></label></div><p id="demo-error" hidden>视频暂时未能播放，请关闭后重新打开。</p><p id="demo-note"></p><a id="demo-source" target="_blank" rel="noopener noreferrer">查看 openGym 动作条目 ↗</a><small>© Aliaksandr Makatserchyk / Gym visual · 180 px 原始素材</small></dialog>`}
function updateSetProgress(){const p=sessionProgress(),log=setLog();$('#completed-sets').textContent=p.done;$('#progress-percent').textContent=p.percent+'%';$('#sets-progress-bar').style.width=p.percent+'%';sessionRows().forEach(e=>{document.querySelector(`[data-exercise-progress="${e.id}"]`).textContent=e.reps.filter((_,i)=>log[setKey(e.id,i)]).length+'/'+e.reps.length+' 组'});$('#start-session').textContent=p.done===p.total?'今日训练已完成 ✓':p.done?'继续训练 →':'开始训练 →'}
function beginRest(seconds){stopTimer();remaining=seconds;deadline=Date.now()+seconds*1000;$('.rest-dock').hidden=false;$('#timer-toggle').textContent='暂停';timerText();interval=setInterval(()=>{remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));timerText();if(!remaining){stopTimer();$('.rest-dock').hidden=true;toast('休息结束，可以开始下一组。')}},200)}
function bindWorkout(){document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{day=b.dataset.day;render(false)});document.querySelectorAll('[data-set]').forEach(b=>b.onclick=()=>{const [id,index]=b.dataset.set.split(':'),log=setLog(),key=setKey(id,index);log[key]=!log[key];save(todayKey()+'-sets',log);b.classList.toggle('complete',log[key]);b.setAttribute('aria-pressed',String(log[key]));b.querySelector('.set-status').textContent=log[key]?'已完成 ✓':'完成';b.classList.remove('current-set');updateSetProgress();if(log[key]&&sessionProgress().done<sessionProgress().total)beginRest(sessionRows().find(e=>e.id===id).rest);else if(sessionProgress().done===sessionProgress().total){stopTimer();$('.rest-dock').hidden=true;toast('今天的训练完成了，好好恢复。')}});$('#reset-session').onclick=()=>{const log=setLog();Object.keys(log).filter(k=>k.startsWith(day+':')).forEach(k=>delete log[k]);save(todayKey()+'-sets',log);render(false);toast('本训练日的组次已重置。')};$('#start-session').onclick=()=>{stopTimer();$('.rest-dock').hidden=true;const log=setLog();for(const e of sessionRows())for(let i=0;i<e.reps.length;i++)if(!log[setKey(e.id,i)]){document.querySelectorAll('.current-set').forEach(x=>x.classList.remove('current-set'));const b=document.querySelector(`[data-set="${e.id}:${i}"]`);b.classList.add('current-set');document.getElementById('plan-'+e.id).scrollIntoView({behavior:'smooth',block:'center'});b.focus({preventScroll:true});return}toast('全部组次已完成。')};$('#timer-skip').onclick=()=>{stopTimer();$('.rest-dock').hidden=true};$('#timer-toggle').onclick=()=>{if(interval){remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));stopTimer();$('#timer-toggle').textContent='继续';timerText()}else beginRest(remaining)};const dialog=$('#exercise-demo-dialog'),video=$('#demo-video');document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>{const m=planMedia(b.dataset.demo);$('#demo-title').textContent=m.title;$('#demo-note').textContent=m.note;$('#demo-source').href='https://github.com/DuarteSantos8/openGym/blob/5fdb229fe40d2299ba0c82b84c86259d73944aba/catalogue/exercises/'+m.id+'.json';$('#demo-error').hidden=true;$('#demo-speed').value='1';$('#demo-play').textContent='播放示范';video.poster='media/opengym/'+m.id+'.webp';video.src='media/opengym/'+m.id+'.mp4';video.playbackRate=1;dialog.showModal();video.play().catch(()=>{})});$('#close-demo').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{video.pause();video.removeAttribute('src');video.load()});$('#demo-play').onclick=()=>{if(video.paused)video.play().catch(()=>$('#demo-error').hidden=false);else video.pause()};video.onplay=()=>$('#demo-play').textContent='暂停示范';video.onpause=()=>$('#demo-play').textContent='播放示范';video.onerror=()=>{if(video.getAttribute('src'))$('#demo-error').hidden=false};$('#demo-speed').onchange=e=>video.playbackRate=+e.target.value}
